import argparse
import csv
import json
from decimal import Decimal


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)

    west_customer_counts = {}
    with open(args["customers_path"], "r", encoding="utf-8", newline="") as customer_file:
        for customer in csv.DictReader(customer_file):
            if customer["region"].casefold() == "west":
                customer_id = customer["customer_id"]
                west_customer_counts[customer_id] = west_customer_counts.get(customer_id, 0) + 1

    total = Decimal("0")
    with open(args["orders_path"], "r", encoding="utf-8", newline="") as order_file:
        for order in csv.DictReader(order_file):
            match_count = west_customer_counts.get(order["customer_id"], 0)
            if match_count:
                total += Decimal(order["amount"]) * match_count

    print(format(total, "f"))


if __name__ == "__main__":
    main()

from argparse import ArgumentParser
import json


def main():
    parser = ArgumentParser()
    parser.add_argument("payload")
    payload = json.loads(parser.parse_args().payload)

    latest = {}
    with open(payload["path"], "r", encoding="utf-8") as source:
        for line in source:
            if not line.strip():
                continue
            record = json.loads(line)
            timestamp = record["ts"]
            if isinstance(timestamp, bool) or not isinstance(timestamp, (int, float)):
                raise ValueError("ts must be numeric")
            user = record["user"]
            if user not in latest or timestamp > latest[user][0]:
                latest[user] = (timestamp, record.get("action"))

    count = sum(action == "logout" for _, action in latest.values())
    print(count, end="")


if __name__ == "__main__":
    main()

import argparse
import json
from decimal import Decimal


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)

    latest = {}
    with open(args["path"], "r", encoding="utf-8") as handle:
        for line in handle:
            if not line.strip():
                continue
            record = json.loads(line, parse_int=Decimal, parse_float=Decimal)
            user = record["user"]
            ts = record["ts"]
            if not isinstance(ts, Decimal):
                ts = Decimal(str(ts))
            if user not in latest or ts > latest[user][0]:
                latest[user] = (ts, record.get("action"))

    print(sum(action == "logout" for _, action in latest.values()))


if __name__ == "__main__":
    main()

import argparse
import json
import re
from pathlib import Path


def is_negated(text, start):
    prefix = text[max(0, start - 60):start]
    return re.search(r"(?:\b(?:no|not|never|without)\b|\bdon't\b|\bdo not\b)(?:\s+\w+){0,3}\s*$", prefix) is not None


def classify(text):
    text = text.lower()
    patterns = {
        "refund": [r"\brefund(?:ed|ing)?\b", r"\bmoney back\b", r"\breimburse(?:ment|d)?\b"],
        "exchange": [r"\bexchange(?:d|ing)?\b", r"\breplace(?:ment|d)?\b", r"\bswap(?:ped|ping)?\b", r"\bdifferent (?:size|color|colour)\b"],
        "cancellation": [r"\bcancel(?:led|ing|lation)?\b", r"\bterminate\b", r"\bstop (?:my |the )?(?:order|subscription|service)\b", r"\bcall (?:it |the order )?off\b"],
    }
    scores = {label: 0 for label in patterns}
    last_mentions = {label: -1 for label in patterns}
    cue_pattern = re.compile(r"\b(?:want|need|request|prefer|please|would like|can you|could you)\b")

    for label, label_patterns in patterns.items():
        for pattern in label_patterns:
            for match in re.finditer(pattern, text):
                if is_negated(text, match.start()):
                    continue
                score = 1
                nearby_prefix = text[max(0, match.start() - 50):match.start()]
                if cue_pattern.search(nearby_prefix):
                    score += 2
                scores[label] += score
                last_mentions[label] = max(last_mentions[label], match.start())

    return max(patterns, key=lambda label: (scores[label], last_mentions[label]))


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = Path(args["path"])
    if str(path) != "/inputs/ticket.txt":
        raise ValueError("path must be /inputs/ticket.txt")
    text = path.read_text(encoding="utf-8", errors="replace")
    print(classify(text))


if __name__ == "__main__":
    main()
